  Object.assign(D.ui, {
    "Ce perso est enchaîné : il ne peut pas être activé ce tour-ci.": "This unit is chained: it can’t be activated this turn.",
    "Une 2e armée, à choisir à la place de la Lumière quand tu commences une partie ou un duel. Tous ses persos ont des pouvoirs à eux : possession, malédictions, portes des ombres, goules, loups-garous… Ses persos se cachent dans le noir : un garde ou un soldat ennemi ne peut pas les prendre à plus de 4 cases. Elle gagne aussi en ayant 3 persos dans la zone de placement adverse.": "A 2nd army, to choose instead of the Light when you start a run or a duel. All its units have powers of their own: possession, curses, shadow gates, ghouls, werewolves… Its units hide in the dark: an enemy guard or soldier can’t capture them from more than 4 squares away. It also wins by having 3 units in the enemy deployment zone.",
    "Le Clan des Ombres : une 2e armée complète (15 dieux, 18 gardes, ses soldats) aux pouvoirs que la Lumière n’a pas, cachée dans le noir": "The Shadow Clan: a complete 2nd army (15 gods, 18 guards, its soldiers) with powers the Light doesn’t have, hidden in the dark",
  });
  Object.assign(D.T, {"na": ["Possession", "Takes control of an enemy soldier or guard next to one of your units: it switches to your side (it counts as lost for the opponent)."], "nb": ["Curse", "Curses an enemy (not a god) anywhere on the map: if it is still on the same square at the end of its side’s next turn, it dies."], "nc": ["Passage", "Sends one of your units (not a god) through the shadows: it comes out on an empty square next to another of your units."], "nd": ["Soul thief", "Steals up to 30 mana from the opponent."], "ne": ["Howl", "All enemies (not gods) in your half of the map move one square back towards their side, if the square is free."], "nf": ["Call of the dead", "Brings 2 Shadows (shadow soldiers) into your reserve, plus 1 per guard you have lost (4 at most)."], "ng": ["Shackle", "Chains an enemy unit (even a god): it can’t be activated during its side’s next 2 turns."], "nh": ["Shadow gate", "Opens a gate: one of your guards or soldiers comes out on an empty square of the enemy deployment zone."], "ni": ["Plague", "All enemy soldiers next to at least 2 of your units die."], "nj": ["Shroud", "Covers one of your units and your units next to it: nothing can kill them until your next turn."], "nk": ["Black tide", "All your Shadows (shadow soldiers) move one square towards the opponent, if the square is free."], "n1": ["Ghost", "Passes through everything: lands on an empty square 3 squares away or less. Where it lands, adjacent enemy soldiers die of fright and adjacent enemy guards can’t be activated on their next turn."], "n2": ["Ghoul", "Takes 1 step in any direction; captures by landing on an enemy. After a capture, it can take another step (3 steps at most)."], "n3": ["Vampire", "Takes 1 step onto an empty square (8 directions), or bites without moving an enemy 1 or 2 squares away in a straight line or diagonally, over everything (not a god): the enemy dies and you gain 20 mana."], "n4": ["Spider", "Takes 1 straight step onto an empty square, or casts its web on the first enemy unit in a straight line 4 squares away or less: a soldier dies there, a guard or god can’t be activated for 2 of its side’s turns."], "n5": ["Poltergeist", "Takes 1 straight step onto an empty square, or grabs an enemy 1 or 2 squares away in a straight line or diagonally (not a god) and throws it 2 squares further: if it lands off the map, in a hole or on a unit, it dies."], "n6": ["Serpent", "Slithers up to 3 straight steps (up, down, left, right), turning as it likes, through empty squares; captures by landing on an enemy."], "n7": ["Werewolf", "Takes 1 step in any direction (captures by landing on an enemy). If it is next to 2 enemies or more, it can go into a frenzy: all enemies next to it die (not gods)."], "n8": ["Larva", "Takes 1 straight step onto an empty square, or captures diagonally. When it dies, 2 Shadows hatch around it."], "n9": ["Demon", "Takes 1 step in any direction (captures by landing on an enemy), or springs up on an empty square next to an enemy god."], "nl": ["Skeleton", "Takes 1 straight step (captures by landing on an enemy), or throws a bone without moving at an enemy 2 or 3 squares away in a straight line (not a god). When it dies, it rises again as a Shadow right next to it."], "nm": ["Reflection", "Takes 1 straight step onto an empty square, or jumps into its reflection: the mirror square on the same row, on the other side (left ↔ right); it captures an enemy there, not a god."], "nn": ["Executioner", "Takes 1 step onto an empty square (8 directions), or executes without moving an enemy next to it (not a god) that is also next to another of your units."], "no": ["Crawler", "Crawls straight towards the opponent, up to 4 squares, through empty squares; captures by landing on an enemy."]});
  D.T.oa[1] = "Takes 1 step onto an empty square, or leaps 2 or 3 squares (straight or diagonal, over everything); captures by landing on an enemy.";
